// The Code sandbox does not expose URLSearchParams as a global, the same way it
// withholds URL. Without this the token request throws "URLSearchParams is not
// defined" on the first line that matters and the whole run dies before it has
// read anything — which is exactly what it did, silently, every fifteen minutes.
const { URLSearchParams } = require('url');

const TENANT = $env.MS_TENANT_ID, CLIENT = $env.MS_CLIENT_ID;
const SECRET = $env.MS_CLIENT_SECRET, UPN = $env.MS_SENDER_UPN;
const GEMINI = $env.GEMINI_API_KEY;
const http = this.helpers.httpRequest;

const SITE = 'bextconsultancy.sharepoint.com:/sites/BEXTHQ';
const BASE = 'API Automation Folder';
const TEMPLATE = BASE + '/Templates/Minutes Template.docx';
const MODEL = 'gemini-3.6-flash';

// The channel is the readable record: one folder per meeting holding the
// transcript, the minutes and the summary, plus PDF renditions for reading.
const CHANNEL_SITE = 'bextconsultancy.sharepoint.com:/sites/bext_transcriptsrecords';
const CHANNEL_BASE = 'Bext Transcripts';
const PROGRAM = 'RACV Property Electrification — Weekly Program Check-in';
const DOCX = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
const WEBHOOK = $env.TEAMS_MEETING_WEBHOOK_URL;

// --- shared document writer, generated from n8n/lib/docx.js — do not edit here ---
/**
 * Plain Word documents and readable transcripts, with no dependencies.
 *
 * Shared by graph/run-meeting-once.js and the Meeting Intake Code node. The Code
 * node is the reason this carries its own ZIP writer: n8n's sandbox exposes only
 * the modules named in NODE_FUNCTION_ALLOW_BUILTIN, pizzip is not in the image,
 * and anything installed into the container by hand is lost on the next rebuild.
 *
 * A .docx is a ZIP of XML. Entries are written with method 0 (stored) — Word
 * accepts uncompressed members, and a few tens of kilobytes of XML is not worth a
 * DEFLATE implementation.
 *
 * IMPORTANT — this file is inlined into a template literal by n8n/build-workflows.js.
 * A backtick or a dollar-brace anywhere here, comments included, would be evaluated
 * at build time and silently corrupt the copy that reaches n8n. Single quotes and
 * string concatenation only.
 */

const CRC_TABLE = (function () {
  const t = [];
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    t[n] = c >>> 0;
  }
  return t;
})();

const crc32 = buf => {
  let c = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xFF] ^ (c >>> 8);
  return (c ^ 0xFFFFFFFF) >>> 0;
};

/** A ZIP archive of {name, data} entries, all stored rather than deflated. */
const zip = files => {
  const parts = [];
  const central = [];
  let offset = 0;
  for (const f of files) {
    const name = Buffer.from(f.name, 'utf8');
    const data = Buffer.isBuffer(f.data) ? f.data : Buffer.from(f.data, 'utf8');
    const sum = crc32(data);

    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4);          // version needed
    local.writeUInt16LE(0, 6);           // flags
    local.writeUInt16LE(0, 8);           // method 0 — stored
    local.writeUInt16LE(0, 10);          // mod time, fixed so output is reproducible
    local.writeUInt16LE(0x21, 12);       // mod date — 1 Jan 1980
    local.writeUInt32LE(sum, 14);
    local.writeUInt32LE(data.length, 18);
    local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(name.length, 26);
    local.writeUInt16LE(0, 28);
    parts.push(local, name, data);

    const dir = Buffer.alloc(46);
    dir.writeUInt32LE(0x02014b50, 0);
    dir.writeUInt16LE(20, 4);            // version made by
    dir.writeUInt16LE(20, 6);            // version needed
    dir.writeUInt16LE(0, 8);
    dir.writeUInt16LE(0, 10);
    dir.writeUInt16LE(0, 12);
    dir.writeUInt16LE(0x21, 14);
    dir.writeUInt32LE(sum, 16);
    dir.writeUInt32LE(data.length, 20);
    dir.writeUInt32LE(data.length, 24);
    dir.writeUInt16LE(name.length, 28);
    dir.writeUInt16LE(0, 30);            // extra
    dir.writeUInt16LE(0, 32);            // comment
    dir.writeUInt16LE(0, 34);            // disk
    dir.writeUInt16LE(0, 36);            // internal attrs
    dir.writeUInt32LE(0, 38);            // external attrs
    dir.writeUInt32LE(offset, 42);
    central.push(dir, name);

    offset += local.length + name.length + data.length;
  }

  const dirBuf = Buffer.concat(central);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(0, 4);
  end.writeUInt16LE(0, 6);
  end.writeUInt16LE(files.length, 8);
  end.writeUInt16LE(files.length, 10);
  end.writeUInt32LE(dirBuf.length, 12);
  end.writeUInt32LE(offset, 16);
  end.writeUInt16LE(0, 20);
  return Buffer.concat([Buffer.concat(parts), dirBuf, end]);
};

const esc = s => String(s === null || s === undefined ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

/**
 * A flat Word document. blocks are { heading } or { text }, and a text block may
 * set tight to suppress the space before it — used for bulleted runs.
 */
const simpleDocx = (title, blocks) => {
  const para = (runs, opts) => '<w:p>'
    + (opts && opts.tight ? '<w:pPr><w:spacing w:before="0" w:after="60"/></w:pPr>' : '')
    + runs + '</w:p>';
  const run = (t, rpr) => '<w:r>' + (rpr || '') + '<w:t xml:space="preserve">' + esc(t) + '</w:t></w:r>';

  const body = [para(run(title, '<w:rPr><w:b/><w:sz w:val="36"/></w:rPr>'))];
  for (const b of blocks || []) {
    if (b.heading) body.push(para(run(b.heading, '<w:rPr><w:b/><w:sz w:val="28"/></w:rPr>')));
    else body.push(para(run(b.text || ''), { tight: b.tight }));
  }

  return zip([
    {
      name: '[Content_Types].xml',
      data: '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        + '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
        + '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
        + '<Default Extension="xml" ContentType="application/xml"/>'
        + '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
        + '</Types>',
    },
    {
      name: '_rels/.rels',
      data: '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        + '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        + '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>'
        + '</Relationships>',
    },
    {
      name: 'word/document.xml',
      data: '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        + '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>'
        + body.join('')
        + '<w:sectPr><w:pgSz w:w="11906" w:h="16838"/>'
        + '<w:pgMar w:top="1134" w:right="1134" w:bottom="1134" w:left="1134"/></w:sectPr>'
        + '</w:body></w:document>',
    },
  ]);
};

/**
 * VTT cues as readable paragraphs, one per speaker turn. Timestamps and cue
 * numbers are dropped — nobody reads a transcript for those — and consecutive
 * lines from one speaker are merged so the result reads as speech rather than
 * as subtitles.
 */
const vttToBlocks = vtt => {
  const out = [];
  let last = null;
  const lines = String(vtt === null || vtt === undefined ? '' : vtt).split(/\r?\n/);
  for (const raw of lines) {
    const line = raw.trim();
    if (!line || /^(WEBVTT|NOTE|STYLE|REGION)\b/.test(line)) continue;
    if (line.indexOf('-->') > -1 || /^\d+$/.test(line)) continue;
    const v = line.match(/^<v\s+([^>]+)>([\s\S]*?)(?:<\/v>)?$/);
    const who = v ? v[1].trim() : null;
    const said = (v ? v[2] : line).replace(/<[^>]+>/g, '').trim();
    if (!said) continue;
    if (who && who === last) out[out.length - 1].text += ' ' + said;
    else if (who) { out.push({ text: who + ':  ' + said }); last = who; }
    else if (last === null && out.length) out[out.length - 1].text += ' ' + said;
    else { out.push({ text: said }); last = null; }
  }
  return out.length ? out : [{ text: '(the transcript was empty)' }];
};

// ─── transcript dedup ────────────────────────────────────────────────────────

const norm = s => String(s || '').toLowerCase()
  .replace(/<[^>]+>/g, ' ').replace(/[^a-z0-9\s]/g, ' ')
  .replace(/\s+/g, ' ').trim();

/** Dice coefficient over word bigrams: 1.0 identical, 0.0 nothing shared.
 *  Bigrams rather than characters because the failure mode is a single wrong
 *  word inside an otherwise identical sentence, which character n-grams score
 *  far too high and single words score too low. */
const similarity = (a, b) => {
  const grams = s => {
    const w = s.split(' ').filter(Boolean);
    if (w.length < 2) return w.slice();
    const g = [];
    for (let i = 0; i < w.length - 1; i++) g.push(w[i] + ' ' + w[i + 1]);
    return g;
  };
  const A = grams(a), B = grams(b);
  if (!A.length || !B.length) return a === b ? 1 : 0;
  const pool = B.slice();
  let hits = 0;
  for (const g of A) {
    const at = pool.indexOf(g);
    if (at > -1) { hits++; pool.splice(at, 1); }
  }
  return (2 * hits) / (A.length + B.length);
};

const toSeconds = ts => {
  const m = String(ts).match(/(\d{2}):(\d{2}):(\d{2})[.,](\d{3})/);
  if (!m) return null;
  return (+m[1]) * 3600 + (+m[2]) * 60 + (+m[3]) + (+m[4]) / 1000;
};

/**
 * Drops the second copy of an utterance when two Teams clients in one call each
 * produce their own stream. The two streams transcribe the same audio slightly
 * differently — "rate cards" and "read cards" — so an exact-match key never
 * catches them, and comparing every line against every other would merge two
 * people who genuinely said the same short thing an hour apart.
 *
 * What identifies a real duplicate is that it says nearly the same words at
 * nearly the same moment. Both conditions are required.
 */
const dedupeVtt = (vtt, opts) => {
  const o = opts || {};
  const threshold = o.threshold === undefined ? 0.75 : o.threshold;
  const window = o.window === undefined ? 10 : o.window;   // seconds

  const lines = String(vtt === null || vtt === undefined ? '' : vtt).split(/\r?\n/);
  const out = [];
  const kept = [];        // { at, text } for comparison
  let dropped = 0;
  let at = null;          // start time of the cue being read
  let skipping = false;

  for (const line of lines) {
    const t = line.match(/(\d{2}:\d{2}:\d{2}[.,]\d{3})\s*-->/);
    if (t) { at = toSeconds(t[1]); skipping = false; out.push(line); continue; }

    if (line.indexOf('<v ') === -1) {
      // A continuation line of a cue that was dropped goes with it.
      if (skipping && line.trim()) { dropped++; continue; }
      out.push(line);
      continue;
    }

    const text = norm(line);
    if (!text) { out.push(line); continue; }

    // The same person appears under different labels across the two streams —
    // "Brent Craig" and "Brent (Teams)" — so match on the first name token.
    const who = (line.match(/<v\s+([^>]+)>/) || [, ''])[1];
    const tag = norm(who).split(' ')[0] || '';
    const words = text.split(' ').length;

    const near = kept.filter(k => at === null || k.at === null
      || Math.abs(k.at - at) <= window);
    const dupe = near.some(k => {
      const sim = similarity(k.text, text);
      // Same speaker: a near match is a duplicate stream.
      if (tag && k.tag && tag === k.tag) return sim >= threshold;
      // Different speakers: only collapse a long, almost-identical utterance.
      // Two people both saying "Agreed." in the same second are two
      // contributions, and dropping one would delete someone from the record.
      return words >= 6 && sim >= 0.9;
    });

    if (dupe) { dropped++; skipping = true; continue; }
    skipping = false;
    kept.push({ at: at, text: text, tag: tag });
    out.push(line);
  }

  return { vtt: out.join('\n'), dropped: dropped };
};



// --- shared card builder, generated from n8n/lib/meeting-card.js — do not edit here ---
/**
 * The Teams channel announcement for a processed meeting.
 *
 * Shared by graph/run-meeting-once.js and the Meeting Intake Code node, which is
 * why it is a pure function: it returns the webhook envelope and posts nothing.
 * The transport differs between the two callers (fetch vs this.helpers.httpRequest)
 * and is deliberately left to them.
 *
 * IMPORTANT — this file is inlined into a template literal by n8n/build-workflows.js.
 * A backtick or a dollar-brace anywhere in here, comments included, would be
 * evaluated at build time and silently corrupt the copy that reaches n8n. Single
 * quotes and string concatenation only. No require, no fetch, no process.env.
 *
 * Adaptive Cards 1.4, not 1.5: the Table element is 1.5 and renders inconsistently
 * through the Power Automate post action, so tables are hand-built from ColumnSets.
 */

// Teams rejects payloads around 28 KB. Build to a lower ceiling and shed detail to
// reach it, because a card that fails to post tells the channel nothing at all.
const CARD_MAX_BYTES = 26000;
const SUMMARY_MAX = 1200;
const ACTION_TITLE_MAX = 90;
const ACTION_ROWS_MAX = 8;

const clip = (s, n) => {
  const t = String(s === null || s === undefined ? '' : s).trim();
  return t.length > n ? t.slice(0, n - 1).replace(/\s+$/, '') + '…' : t;
};

const isClosed = a =>
  a.closed === true || /closed|complete|done/i.test(String(a.status || ''));

const text = (s, opts) => {
  const o = { type: 'TextBlock', text: s, wrap: true };
  for (const k in (opts || {})) o[k] = opts[k];
  return o;
};

const heading = s => text(s, { weight: 'Bolder', size: 'Medium', spacing: 'Medium' });

// A chip is a tinted Container, not a pill — Adaptive Cards has no border radius.
// A ColumnSet does not wrap either, so callers cap each row at four.
const chipRow = (chips, spacing) => ({
  type: 'ColumnSet',
  spacing: spacing || 'Small',
  columns: chips.slice(0, 4).map(c => ({
    type: 'Column',
    width: 'auto',
    items: [{
      type: 'Container',
      style: c.style || 'emphasis',
      items: [text(c.text, { size: 'Small', weight: 'Bolder', wrap: false, spacing: 'None' })],
    }],
  })),
});

const tableRow = (cells, opts) => {
  const o = opts || {};
  const widths = ['stretch', 'auto', 'auto', 'auto'];
  return {
    type: 'Container',
    separator: o.separator === true,
    spacing: 'Small',
    items: [{
      type: 'ColumnSet',
      columns: cells.map((c, i) => ({
        type: 'Column',
        width: widths[i] || 'auto',
        items: [text(c.text, {
          size: 'Small',
          weight: o.header ? 'Bolder' : 'Default',
          isSubtle: o.header === true,
          color: c.color || 'Default',
        })],
      })),
    }],
  };
};

/**
 * m = {
 *   subject, program, meetingNo, date, time, venue, organiser,
 *   attendees: [{ name }] or [string],
 *   summary, decisions: [string],
 *   actions:  [{ title, owner, due, status, closed }],
 *   projects: [{ status }], safety: [{ status }],
 *   urls: { folder, minutes, summary, transcript },
 * }
 */
const buildCard = (m, limits) => {
  const lim = limits || {};
  const rowsMax = lim.rows === undefined ? ACTION_ROWS_MAX : lim.rows;
  const actions = (m.actions || []).slice();
  const decisions = lim.dropDecisions ? [] : (m.decisions || []);
  // Attendees carry an Entra id only when the name resolved to a real account.
  // Those become Teams @mentions so the people in the room are notified; the rest
  // stay plain text. A transcript gives names, not addresses, so partial
  // resolution is the normal case rather than a failure.
  const people = (m.attendees || [])
    .map(a => (typeof a === 'string' ? { name: a } : (a || {})))
    .filter(a => a.name);
  const attendees = people.map(a => a.name);
  const entities = [];
  const mentionText = people.map(a => {
    if (!a.id) return clip(a.name, 60);
    const tag = '<at>' + clip(a.name, 60) + '</at>';
    entities.push({ type: 'mention', text: tag, mentioned: { id: a.id, name: clip(a.name, 60) } });
    return tag;
  }).join(', ');

  const open = actions.filter(a => !isClosed(a)).length;
  const closed = actions.length - open;
  const atRisk = (m.projects || []).filter(p => /at risk/i.test(String(p.status || ''))).length;
  const safetyOpen = (m.safety || []).filter(s => !/closed/i.test(String(s.status || ''))).length;

  const body = [];

  body.push(text(clip(m.subject || 'Meeting record', 140), { size: 'Large', weight: 'Bolder' }));
  if (m.program) body.push(text(clip(m.program, 140), { isSubtle: true, spacing: 'None' }));

  const row1 = [];
  if (m.program) row1.push({ text: clip(m.program, 40) });
  if (m.meetingNo) row1.push({ text: 'Meeting #' + m.meetingNo });
  if (m.date) row1.push({ text: String(m.date) });
  if (row1.length) body.push(chipRow(row1, 'Medium'));

  const row2 = [];
  if (open) row2.push({ text: open + (open === 1 ? ' action open' : ' actions open'), style: 'attention' });
  if (closed) row2.push({ text: closed + ' closed', style: 'good' });
  if (atRisk) row2.push({ text: atRisk + (atRisk === 1 ? ' project at risk' : ' projects at risk'), style: 'warning' });
  if (safetyOpen) row2.push({ text: 'Safety: ' + safetyOpen + ' open', style: 'warning' });
  if (row2.length) body.push(chipRow(row2));

  const facts = [];
  if (m.date) facts.push({ title: 'Date', value: String(m.date) });
  if (m.time) facts.push({ title: 'Time', value: String(m.time) });
  if (m.venue) facts.push({ title: 'Venue', value: String(m.venue) });
  if (m.organiser) facts.push({ title: 'Organiser', value: String(m.organiser) });
  if (facts.length) body.push({ type: 'FactSet', spacing: 'Medium', facts: facts });

  if (attendees.length) {
    // Not clipped: truncating mid-tag would leave a broken <at> that Teams renders
    // as literal markup. The mention list is short by nature.
    body.push(text('Attendees: ' + mentionText, { isSubtle: true, size: 'Small' }));
  }

  if (m.summary) {
    body.push(heading('Summary'));
    body.push(text(clip(m.summary, SUMMARY_MAX), { spacing: 'Small' }));
  }

  if (decisions.length) {
    body.push(heading('Decisions'));
    decisions.forEach(d => body.push(text('•  ' + clip(d, 200), { spacing: 'Small', size: 'Small' })));
  }

  if (actions.length && rowsMax > 0) {
    body.push(heading('Actions'));
    body.push(tableRow(
      [{ text: 'Action' }, { text: 'Owner' }, { text: 'Due' }, { text: 'Status' }],
      { header: true },
    ));
    actions.slice(0, rowsMax).forEach(a => body.push(tableRow([
      { text: clip(a.title, ACTION_TITLE_MAX) },
      { text: clip(a.owner || 'Unassigned', 24) },
      { text: a.due ? String(a.due) : '—' },
      { text: isClosed(a) ? 'Done' : 'Open', color: isClosed(a) ? 'Good' : 'Attention' },
    ], { separator: true })));
    if (actions.length > rowsMax) {
      body.push(text('+ ' + (actions.length - rowsMax) + ' more — see Minutes.docx',
        { size: 'Small', isSubtle: true, spacing: 'Small' }));
    }
  }

  // An Action.OpenUrl with an empty url fails validation and 400s the whole post,
  // so every button is conditional on its link having survived the upload.
  const u = m.urls || {};
  const buttons = [];
  const link = (title, url) => { if (url) buttons.push({ type: 'Action.OpenUrl', title: title, url: url }); };
  link('Open meeting folder', u.folder);
  link('Minutes.docx', u.minutes);
  link('Summary.docx', u.summary);
  link('Transcript.vtt', u.transcript);

  const content = {
    $schema: 'http://adaptivecards.io/schemas/adaptive-card.json',
    type: 'AdaptiveCard',
    version: '1.4',
    body: body,
    actions: buttons,
  };
  // Teams reads mentions from this card-level block, not from the TextBlock. An
  // <at> tag without a matching entity renders as literal markup, so the two are
  // emitted together or not at all.
  if (entities.length) content.msteams = { entities: entities };

  return {
    type: 'message',
    attachments: [{
      contentType: 'application/vnd.microsoft.card.adaptive',
      contentUrl: null,
      content: content,
    }],
  };
};

/**
 * Builds the card, shedding detail until it fits under the Teams size cap.
 * Order of sacrifice: action rows first, then decisions — the summary and the
 * links are the point of the card and are never dropped.
 */
const buildMeetingCard = m => {
  let card = buildCard(m, {});
  if (JSON.stringify(card).length <= CARD_MAX_BYTES) return card;

  const steps = [
    { rows: 4 }, { rows: 2 }, { rows: 0 },
    { rows: 0, dropDecisions: true },
  ];
  for (let i = 0; i < steps.length; i++) {
    card = buildCard(m, steps[i]);
    if (JSON.stringify(card).length <= CARD_MAX_BYTES) return card;
  }
  return card;
};



// --- shared email builder, generated from n8n/lib/meeting-email.js — do not edit here ---
// Wrapped in its own scope: the card builder and the email builder both define
// SUMMARY_MAX, clip and isClosed, and inlining them side by side in one scope is
// a redeclaration error. Isolating here beats renaming things in a file that has
// its own tests and its own reader.
const buildMeetingEmail = (function () {
/**
 * The follow-up email for a processed meeting, in the client's own format.
 *
 * Shared by graph/run-meeting-once.js and the Meeting Intake Code node, which is
 * why it is a pure function: it returns the message and sends nothing. The
 * transport differs between the two callers (fetch vs this.helpers.httpRequest)
 * and the attachment is fetched by them, not here.
 *
 * The shape is the client's worked example, not our invention:
 *
 *   [Morning/Afternoon/Evening] All,
 *   Please see attached minutes following recent meeting {subject} {date}.
 *   A quick summary below for reference.
 *   Highlights            one bullet per project, prose
 *   Closed in today's meeting
 *   Remaining open actions grouped by organisation, then by owner
 *
 * This file is inlined into a template literal by n8n/build-workflows.js. Single
 * quotes and concatenation only — not because interpolation would corrupt it
 * (it would not; see docs/REGRESSIONS.md R005b) but because the surrounding
 * files are written that way and mixing styles here invites the wrong fix later.
 */

// Outlook drops enormous bodies and the useful content is the summary, not the
// tail of a long action list. Bound the parts that can grow without limit.
const SUMMARY_MAX = 1500;
const BULLET_MAX = 400;
const ACTIONS_PER_OWNER = 6;

const esc = s => String(s === null || s === undefined ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const clip = (s, n) => {
  const t = String(s === null || s === undefined ? '' : s).trim();
  return t.length > n ? t.slice(0, n - 1).replace(/\s+$/, '') + '…' : t;
};

const isClosed = x =>
  x.closed === true || /closed|complete|done/i.test(String(x.status || ''));

/**
 * Morning before noon, Afternoon to 17:00, Evening after. Computed in the
 * meeting's own timezone: a 9am Melbourne meeting is a morning meeting even when
 * the pipeline processes it from another timezone hours later.
 */
const greeting = (startIso, timeZone) => {
  const d = startIso ? new Date(startIso) : new Date();
  if (isNaN(d.getTime())) return 'Morning';
  let hour;
  try {
    hour = Number(new Intl.DateTimeFormat('en-AU', {
      timeZone: timeZone || 'Australia/Melbourne', hour: 'numeric', hour12: false,
    }).format(d));
  } catch (e) { hour = d.getHours(); }
  if (hour < 12) return 'Morning';
  if (hour < 17) return 'Afternoon';
  return 'Evening';
};

const longDate = (startIso, timeZone) => {
  const d = startIso ? new Date(startIso) : new Date();
  if (isNaN(d.getTime())) return '';
  try {
    return new Intl.DateTimeFormat('en-AU', {
      timeZone: timeZone || 'Australia/Melbourne',
      day: 'numeric', month: 'long', year: 'numeric',
    }).format(d);
  } catch (e) { return d.toISOString().slice(0, 10); }
};

/**
 * Which organisation an action's owner belongs to.
 *
 * participants is [{ name, organisation, email }] from the participants table —
 * the authoritative mapping, because a person's employer is not derivable from a
 * transcript. The domain fallback covers someone who has not been seeded yet;
 * a personal address falls through to "Other", which is visibly wrong in the
 * email and therefore gets fixed, rather than being silently mis-filed.
 */
const orgFor = (owner, participants, domainMap) => {
  const name = String(owner || '').trim();
  if (!name || /^unassigned$/i.test(name)) return 'Unassigned';

  const lower = name.toLowerCase();
  for (const p of (participants || [])) {
    // participants.company is the column; organisation is accepted so a caller
    // can pass a plain object without renaming.
    const org = p.company || p.organisation;
    const names = [p.name].concat(p.aliases || []).map(n => String(n || '').toLowerCase()).filter(Boolean);
    const hit = names.some(pn => pn === lower || pn.split(' ')[0] === lower.split(' ')[0]);
    if (!hit) continue;
    if (org) return org;
    const dom = String(p.email || '').split('@')[1];
    if (dom && domainMap && domainMap[dom]) return domainMap[dom];
  }
  const dom = String(name).indexOf('@') > -1 ? name.split('@')[1] : '';
  if (dom && domainMap && domainMap[dom]) return domainMap[dom];
  return 'Other';
};

/**
 * m = {
 *   subject, date, startIso, timeZone,
 *   summary, decisions: [string],
 *   projects: [{ project, status, highlight, update, next_action }],
 *   safety:  [{ item, status }],
 *   finance: [{ item, status }],
 *   actions: [{ title, owner, due, status, closed }],
 *   participants: [{ name, organisation, email }],
 *   domainMap: { 'racv.com.au': 'RACV' },
 *   urls: { folder, minutes },
 * }
 *
 * Returns { subject, html, text, sections } — sections is exposed so a caller can
 * assert on the parts without re-parsing HTML.
 */
const buildMeetingEmail = m => {
  const tz = m.timeZone || 'Australia/Melbourne';
  const when = longDate(m.startIso, tz);
  const hello = greeting(m.startIso, tz);

  // ── Highlights — one line per project ──────────────────────────────────────
  // Prefer the model's prose. Fall back to assembling something honest from the
  // structured fields rather than dropping the project silently.
  const highlights = (m.projects || []).map(p => {
    const name = clip(p.project || 'Project', 80);
    let body = p.highlight || p.update || '';
    if (!body && p.next_action) body = 'Next: ' + p.next_action;
    if (!body) body = p.status || '';
    else if (p.status && !new RegExp(p.status, 'i').test(body)) body = body + ' (' + p.status + ')';
    return { project: name, text: clip(body, BULLET_MAX) };
  }).filter(h => h.text);

  // ── Closed in today's meeting ──────────────────────────────────────────────
  // Decisions are the explicit ones; anything that moved to Closed counts too.
  // A decision and the action it closed are usually the same thing said twice.
  // Dedupe on a loose key so the reader sees one line, not an echo.
  const closedSeen = {};
  const closed = []
    .concat(m.decisions || [])
    .concat((m.actions || []).filter(isClosed).map(a => a.title))
    .concat((m.safety || []).filter(isClosed).map(s => s.item))
    .concat((m.finance || []).filter(isClosed).map(f => f.item))
    .map(s => clip(s, BULLET_MAX))
    .filter(Boolean)
    .filter(s => {
      // Drop leading articles and trailing bookkeeping words so "the baseline
      // programme" and "Baseline programme sign-off" collapse to one line.
      const key = s.toLowerCase()
        .replace(/[^a-z0-9]+/g, ' ')
        .replace(/^(the|a|an) /, '')
        .replace(/ (sign off|signoff|confirmed|complete|completed|done|closed)$/, '')
        .trim();
      if (!key || closedSeen[key]) return false;
      // also catch one being a prefix of the other ("baseline programme" vs
      // "baseline programme sign-off")
      for (const seen in closedSeen) {
        if (seen.indexOf(key) === 0 || key.indexOf(seen) === 0) return false;
      }
      closedSeen[key] = true;
      return true;
    });

  // ── Remaining open actions, by organisation then owner ────────────────────
  const open = (m.actions || []).filter(a => !isClosed(a));
  const byOrg = {};
  for (const a of open) {
    const org = orgFor(a.owner, m.participants, m.domainMap);
    const owner = String(a.owner || 'Unassigned').trim() || 'Unassigned';
    byOrg[org] = byOrg[org] || {};
    byOrg[org][owner] = byOrg[org][owner] || [];
    if (byOrg[org][owner].length < ACTIONS_PER_OWNER) {
      const due = a.due ? ' (due ' + a.due + ')' : '';
      byOrg[org][owner].push(clip(a.title, BULLET_MAX) + due);
    }
  }
  // Unassigned last: it is a prompt to the reader, not a section they own.
  const orgNames = Object.keys(byOrg).sort((x, y) => {
    const rank = n => (n === 'Unassigned' ? 2 : n === 'Other' ? 1 : 0);
    return rank(x) - rank(y) || x.localeCompare(y);
  });

  // ── render ────────────────────────────────────────────────────────────────
  const h = [];
  const t = [];
  const P = s => { h.push('<p>' + s + '</p>'); };
  const UL = items => {
    h.push('<ul>');
    for (const i of items) h.push('<li>' + i + '</li>');
    h.push('</ul>');
  };

  P(esc(hello) + ' All,');
  t.push(hello + ' All,', '');

  const ref = esc(clip(m.subject || 'the meeting', 140)) + (when ? ', ' + esc(when) : '');
  P('Please see attached minutes following recent meeting ' + ref + '.');
  P('A quick summary below for reference.');
  t.push('Please see attached minutes following recent meeting ' +
    clip(m.subject || 'the meeting', 140) + (when ? ', ' + when : '') + '.',
    'A quick summary below for reference.', '');

  if (m.summary) {
    P(esc(clip(m.summary, SUMMARY_MAX)));
    t.push(clip(m.summary, SUMMARY_MAX), '');
  }

  if (highlights.length) {
    h.push('<p><b>Highlights</b></p>');
    UL(highlights.map(x => '<b>' + esc(x.project) + '</b> — ' + esc(x.text)));
    t.push('Highlights');
    highlights.forEach(x => t.push('* ' + x.project + ' — ' + x.text));
    t.push('');
  }

  if (closed.length) {
    h.push('<p><b>Closed in today\'s meeting</b></p>');
    UL(closed.map(esc));
    t.push("Closed in today's meeting");
    closed.forEach(c => t.push('* ' + c));
    t.push('');
  }

  if (orgNames.length) {
    h.push('<p><b>Remaining open actions</b></p>');
    t.push('Remaining open actions');
    for (const org of orgNames) {
      h.push('<p><b>' + esc(org) + '</b></p>');
      t.push(org);
      const owners = Object.keys(byOrg[org]).sort();
      // Under the Unassigned heading the owner name adds nothing — the heading
      // already says it. Print the action alone.
      const line = o => (org === 'Unassigned' && /^unassigned$/i.test(o))
        ? byOrg[org][o].join('; ')
        : o + ' — ' + byOrg[org][o].join('; ');
      UL(owners.map(o => esc(line(o))));
      owners.forEach(o => t.push('* ' + line(o)));
      t.push('');
    }
  }

  if (m.urls && m.urls.folder) {
    P('<a href="' + esc(m.urls.folder) + '">Open the full record</a>');
    t.push('Full record: ' + m.urls.folder);
  }

  return {
    subject: (m.subject || 'Meeting') + ' — minutes' + (when ? ', ' + when : ''),
    html: h.join('\n'),
    text: t.join('\n'),
    sections: {
      greeting: hello, date: when,
      highlights: highlights.length,
      closed: closed.length,
      openActions: open.length,
      organisations: orgNames,
    },
  };
};



  return buildMeetingEmail;
})();
// --- end shared code ---

// Meetings already minuted, passed down from the database. Re-filing a meeting
// every fifteen minutes would bury the reviewer in duplicates.
// One input carrying two kinds of row — see the query on the node before this.
const inputRows = $input.all().map(i => i.json);
const done = new Set(
  inputRows.filter(r => r.kind === 'done').map(r => r.a).filter(Boolean));
const ALREADY_SENT = new Set(
  inputRows.filter(r => r.kind === 'sent').map(r => r.a).filter(Boolean));
const PARTICIPANTS = inputRows
  .filter(r => r.kind === 'participant')
  .map(r => ({ name: r.a, company: r.b, email: r.c, aliases: r.d || [] }));

const auth = await http({
  method: 'POST',
  url: `https://login.microsoftonline.com/${TENANT}/oauth2/v2.0/token`,
  json: true, timeout: 30000,
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({
    client_id: CLIENT, client_secret: SECRET,
    scope: 'https://graph.microsoft.com/.default', grant_type: 'client_credentials',
  }).toString(),
});
const TOKEN = auth.access_token;
const G = 'https://graph.microsoft.com/v1.0';

// There are eight outbound calls in the per-meeting block and axios reports all of
// them the same way: "Request failed with status code 401". That message names
// neither the endpoint nor the response body, which turned a one-line fault into a
// guessing game. Every risky call goes through this so the recorded error says
// which one, with the status and the first of the body.
// ignoreHttpStatusErrors is an HTTP Request NODE option — the Code node's http
// helper does not honour it, so catching is the only way.
const call = async (label, opts) => {
  try {
    return await http(opts);
  } catch (e) {
    const st = e.statusCode || e.status || (e.response && e.response.status) || '?';
    const b = (e.response && (e.response.body || e.response.data)) || e.message || '';
    throw new Error(label + ' ' + st + ': ' + String(typeof b === 'string' ? b : JSON.stringify(b)).slice(0, 220));
  }
};

// graph() is used a dozen times and, unlabelled, every one of its failures reads
// "Request failed with status code 401" with no hint which endpoint. That cost a
// full debugging cycle: the labelled call() wrappers went on the obvious suspects
// and the real failure turned out to be somewhere graph() was used instead.
const graph = async (path, opts = {}) => {
  try {
    return await graphRaw(path, opts);
  } catch (e) {
    const st = e.statusCode || e.status || (e.response && e.response.status) || '?';
    const b = (e.response && (e.response.body || e.response.data)) || e.message || '';
    const method = (opts.method || 'GET');
    throw new Error('graph ' + method + ' ' + path.split('?')[0] + ' -> ' + st + ': '
      + String(typeof b === 'string' ? b : JSON.stringify(b)).slice(0, 200));
  }
};

// Normalise whatever the HTTP helper hands back for a binary response.
//
// With json: true it parses the body, and a binary payload becomes the JSON
// envelope { type: 'Buffer', data: [ ... ] }. Buffer.from() on that object does
// not fail — it produces the *text* of the envelope, which then gets uploaded
// with a .docx extension. Word opens it and reports "unreadable content", which
// reads as a corrupt template or a SharePoint permissions problem rather than a
// response-parsing one. Every binary body goes through here.
const toBuf = v => {
  if (Buffer.isBuffer(v)) return v;
  if (v && v.type === 'Buffer' && Array.isArray(v.data)) return Buffer.from(v.data);
  if (v instanceof ArrayBuffer) return Buffer.from(v);
  if (typeof v === 'string') return Buffer.from(v, 'binary');
  return Buffer.from(v);
};

const graphRaw = (path, opts = {}) => {
  const url = G + path;
  const headers = { Authorization: 'Bearer ' + TOKEN, ...(opts.headers || {}) };

  // opts is spread BEFORE headers, deliberately.
  //
  // The other order — headers first, then ...opts — silently drops Authorization
  // on any call that passes headers of its own. The draft creation passes a
  // Content-Type, so it lost its token and Graph answered 401, while every GET
  // (which passes no headers) kept working. That mismatch is why this read as
  // "Microsoft is rejecting us" for hours: it was our own object spread, not
  // permissions, not licensing, not the n8n HTTP client.
  //
  // headers already merges opts.headers, so putting it last loses nothing.
  return http({
    url: url, json: true, timeout: 60000,
    ...opts,
    headers: headers,
  });
};

// The meetings API rejects a UPN and requires the object id, unlike mail and
// calendar which accept either.
const me = await graph('/users/' + encodeURIComponent(UPN) + '?$select=id,displayName');

// The drive is resolved once, by id. Addressing a library through the compound
// /sites/host:/sites/name:/drive/root:/path form returns 400 — the site path and
// the item path cannot both be relative in one URL.
const site = await graph('/sites/' + SITE);
const drives = await graph('/sites/' + site.id + '/drives');
const DRIVE = (drives.value.find(d => d.name === 'Documents') || drives.value[0]).id;

// Discovery is by transcript, not by calendar. Walking one mailbox's calendar
// missed every meeting somebody else organised — on this tenant that was most of
// them, because Brent books the weekly. getAllTranscripts asks the question we
// actually have ("what has been transcribed?") instead of the one the calendar
// can answer ("what was I invited to?"), and it still returns a meeting whose
// event has since been deleted or declined.
//
// Two traps, both silent:
//   - meetingOrganizerUserId is a required FUNCTION parameter, not a query one.
//     Omit it and Graph answers 400 with a message that reads like a bad URL.
//   - $filter=createdDateTime is ACCEPTED AND IGNORED. Filtering has to happen
//     here, or a full history is reprocessed on every tick.
// Same variable graph/run-meeting-once.js and graph/verify-meeting-access.js read,
